    35	const pendingReviewMarkerFilename = "review-pending.json"
    36	
    37	// PendingReviewMarker is written by `entire review` before spawning the agent.
    38	// The next agent session's UserPromptSubmit hook reads it, tags the session
    39	// kind/review-skills, then clears the marker (so a second review run doesn't
    40	// inherit state from the first).
    41	//
    42	// WorktreePath scopes the marker to the worktree `entire review` was invoked
    43	// from: multiple worktrees in one repo share .git/entire-sessions/, so without
    44	// this field any session in any worktree could race to claim the marker. A
    45	// blank WorktreePath (pre-fix markers) falls back to the legacy unscoped
    46	// behavior — any session can adopt.
    47	type PendingReviewMarker struct {
    48		AgentName    string    `json:"agent_name"`
    49		Skills       []string  `json:"skills"`
    50		StartingSHA  string    `json:"starting_sha"`
    51		StartedAt    time.Time `json:"started_at"`
    52		WorktreePath string    `json:"worktree_path,omitempty"`
    53	}
    54	
    55	func pendingMarkerPath(ctx context.Context) (string, error) {
    56		commonDir, err := session.GetGitCommonDir(ctx)
    57		if err != nil {
    58			return "", fmt.Errorf("locate git common dir: %w", err)
    59		}
    60		return filepath.Join(commonDir, session.SessionStateDirName, pendingReviewMarkerFilename), nil
    61	}
    62	
    63	// WritePendingReviewMarker persists the marker. Overwrites any existing marker.
    64	func WritePendingReviewMarker(ctx context.Context, m PendingReviewMarker) error {
    65		path, err := pendingMarkerPath(ctx)
    66		if err != nil {
    67			return err
    68		}
    69		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
    70			return fmt.Errorf("create sessions dir: %w", err)
    71		}
    72		data, err := json.MarshalIndent(m, "", "  ")
    73		if err != nil {
    74			return fmt.Errorf("marshal marker: %w", err)
    75		}
    76		if err := os.WriteFile(path, data, 0o600); err != nil {
    77			return fmt.Errorf("write marker: %w", err)
    78		}
    79		return nil
    80	}
