    82	// ReadPendingReviewMarker returns the marker if one exists.
    83	// ok=false with err=nil indicates "no pending review."
    84	func ReadPendingReviewMarker(ctx context.Context) (PendingReviewMarker, bool, error) {
    85		path, err := pendingMarkerPath(ctx)
    86		if err != nil {
