   597	func gitLines(ctx context.Context, repoRoot string, args ...string) ([]string, error) {
   598		full := append([]string{"-C", repoRoot}, args...)
   599		output, err := exec.CommandContext(ctx, "git", full...).Output()
   600		if err != nil {
   601			return nil, fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
   602		}
   603		trimmed := strings.TrimSpace(string(output))
   604		if trimmed == "" {
   605			return nil, nil
   606		}
   607		lines := strings.Split(trimmed, "\n")
   608		result := lines[:0]
   609		for _, line := range lines {
   610			if line = strings.TrimSpace(line); line != "" {
   611				result = append(result, line)
   612			}
   613		}
   614		return result, nil
   615	}
