   770			return reviewScope{}, fmt.Errorf("locate repo root: %w", err)
   771		}
   772		var s reviewScope
   773		s.Branch = gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
   774		if s.Branch == detachedHEADDisplay {
   775			s.Branch = ""
   776		}
   777		s.HeadSHA = gitString(ctx, repoRoot, "rev-parse", "--short", "HEAD")
   778		base := detectBaseBranchRef(ctx, repoRoot)
   779		s.Base = base.display
   780		s.BaseRef = base.ref
