   804	func detectBaseBranchRef(ctx context.Context, repoRoot string) baseBranchRef {
   805		if target := gitString(ctx, repoRoot, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); target != "" {
   806			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", target) {
   807				return baseBranchRef{display: strings.TrimPrefix(target, "origin/"), ref: target}
   808			}
   809		}
   810		candidates := []string{defaultBaseBranch, masterBaseBranch}
   811		for _, candidate := range candidates {
   812			ref := "origin/" + candidate
   813			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/remotes/"+ref) {
   814				return baseBranchRef{display: candidate, ref: ref}
   815			}
   816		}
   817		for _, candidate := range candidates {
   818			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/heads/"+candidate) {
   819				return baseBranchRef{display: candidate, ref: candidate}
   820			}
   821		}
   822		return baseBranchRef{}
   823	}
